    private final long count;

    public OwnerDailyLimitExceededException(LocalDate date, long count) {
        super("Already created " + count + " owners on " + date + "; the daily limit is 100");
        this.date = date;
        this.count = count;
    }

    public LocalDate getDate() {
        return date;
    }

    public long getCount() {
        return count;
    }
}

